    const result = createHistogramData(
      [{ value: 0 }, { value: 0.857 }, { value: 1 }],
      7,
      7,
    );

expect(result.chartData.map((bin) => bin.count)).toEqual([
      1, 0, 0, 0, 0, 1, 1,
    ]);
    expect(new Set(result.chartData.map((bin) => bin.binLabel))).toHaveLength(7);
  });
});
